            // we can't simply fix this and map 3 to the correct level, since doing so has the potential
            // to change the look of existing scenes dramatically.
            // NOTE: the table skips the 32x32 mipmap
            const skyboxMapping = [
                0,
                1,
                /* 2 */ 3,
                4,
                5,
                6
            ];
