        this.bundles.destroy();
        this.bundles = null;
        this.i18n.destroy();
        this.i18n = null;
        const scriptHandler = this.loader.getHandler("script");
        scriptHandler?.clearCache();
        this.loader.destroy();
        this.loader = null;
        this.scene.destroy();
        this.scene = null;
        this.systems = null;
        this.context = null;
        // script registry
        this.scripts.destroy();
        this.scripts = null;
        this.scenes.destroy();
        this.scenes = null;
        this.lightmapper?.destroy();
